import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import './styles/global.css';
// MapLibre GL CSS for map rendering (required by react-map-gl)
import 'maplibre-gl/dist/maplibre-gl.css';
// i18n initialization (must be imported before App)
import './i18n/i18n';
import { useUIStore } from './stores/uiStore';
import { useMapStore } from './stores/mapStore';
import { DETAIL_LEVEL_PRESETS, detectDetailLevel } from './utils/detailLevelUtils';
import { registerMapWorker } from './config/mapWorker';
import { resetStaleCache } from './features/cache/cacheReset';

// Must run before any Map is constructed: MapLibre caches its worker pool globally.
// No RTL text plugin is registered — MapLibre >= 6.9 shapes Arabic and Hebrew
// natively, and a plugin set via setRTLTextPlugin would replace that built-in code.
// Caveat: styles using `font-faces` still need the plugin to shape across cluster
// boundaries; none of our basemap styles (liberty, positron, satellite) use it.
registerMapWorker();

declare const __BUILD_TIMESTAMP__: string;
console.log(`%cChronas build: ${__BUILD_TIMESTAMP__}`, 'color: #888; font-size: 10px;');

// Apply the persisted detail-level preset synchronously before React mounts
// so MapView's initial marker fetch honors the user's chosen tier (Issue #8).
(() => {
  const ui = useUIStore.getState();
  const level = ui.detailLevel ?? detectDetailLevel();
  if (ui.detailLevel === null) ui.setDetailLevel(level);
  const preset = DETAIL_LEVEL_PRESETS[level];
  const map = useMapStore.getState();
  map.setMarkerLimit(preset.markerLimit);
  map.setClusterMarkers(preset.clusterMarkers);
})();

// Avant tout montage React : aucun composant n'a encore lancé de requête, donc
// le reset ne peut pas invalider une réponse d'API en vol (bug « No Data
// Available » au premier chargement après un déploiement).
resetStaleCache();

const rootElement = document.getElementById('root');

if (!rootElement) {
  throw new Error(
    'Root element not found. Make sure there is a <div id="root"></div> in your HTML.'
  );
}

createRoot(rootElement).render(
  <StrictMode>
    <App />
  </StrictMode>
);
